# [SAME-SCENARIO] query_metric_window.py\n\nfrom observability_client import get_azure_monitor_client\nfrom observability_models import MetricQueryRequest, MetricQueryResponse\n\ndef query_metric_window(metric_name: str, start_time: str, end_time: str, resource_id: str = None) -> MetricQueryResponse:\n    \"\"\"Query recent datapoints for a named metric over a time window using Azure Monitor Metrics.\n    Uses Azure Monitor Metrics SDK (azure-mgmt-monitor) with Azure AD authentication.\n    Args:\n        metric_name: Name of the metric to query.\n        start_time: ISO 8601 start time (e.g., '2024-06-15T00:00:00Z').\n        end_time: ISO 8601 end time.\n        resource_id: Optional Azure resource ID to scope the query.\n    Returns:\n        MetricQueryResponse object containing datapoints.\n    \"\"\"\n    client = get_azure_monitor_client()\n    request = MetricQueryRequest(metric=metric_name, start_time=start_time, end_time=end_time,\n                                 aggregation='Average', interval='PT1M', resource_id=resource_id)\n    response = client.query.get(resource_id, [request])\n    return response